<script setup lang="ts">
import { CalendarDays, MapPin, Share2 } from '@lucide/vue'
import { eventTheme } from '~~/shared/themes'
import { openStreetMapEmbedUrl } from '~~/shared/map-location'
import { ticketTypeLabel } from '~~/shared/template'
const route = useRoute(); const slug = String(route.params.slug); const k = route.query.k ? String(route.query.k) : undefined
const { data: ev, error } = await useAsyncData(`ev-${slug}`, () => api<any>(`/api/events/${slug}`, { query: { k } }))
if (error.value) throw createError({ statusCode: 404, statusMessage: 'Événement introuvable', fatal: true })
const theme = computed(() => eventTheme(ev.value?.themeId, ev.value?.customTheme)); const vars = computed(() => toStyle(cssVars(theme.value)))
const url = useRequestURL(); const shareUrl = computed(() => `${url.origin}/events/${slug}${k ? `?k=${k}` : ''}`)
useSeoMeta({ title: () => ev.value?.title, description: () => (ev.value?.description || '').slice(0, 155), ogTitle: () => ev.value?.title, ogDescription: () => (ev.value?.description || '').slice(0, 155), ogImage: () => ev.value?.posterUrl, twitterCard: 'summary_large_image', robots: () => (ev.value?.visibility === 'public' && ev.value?.status === 'published' && !ev.value?.isDemo ? 'index, follow' : 'noindex, nofollow') })
useHead(() => ev.value ? { script: [{ type: 'application/ld+json', innerHTML: JSON.stringify({ '@context': 'https://schema.org', '@type': 'Event', name: ev.value.title, startDate: ev.value.startsAt, endDate: ev.value.endsAt, eventStatus: 'https://schema.org/EventScheduled', eventAttendanceMode: 'https://schema.org/OfflineEventAttendanceMode', location: { '@type': 'Place', name: ev.value.location?.venue, address: ev.value.location?.address || ev.value.location?.city }, image: ev.value.posterUrl ? [ev.value.posterUrl] : undefined, offers: ev.value.categories.map((c: any) => ({ '@type': 'Offer', price: c.price, priceCurrency: ev.value.currency, availability: c.soldOut ? 'https://schema.org/SoldOut' : 'https://schema.org/InStock', url: shareUrl.value })), organizer: { '@type': 'Organization', name: ev.value.organizer } }) }] } : {})
const qrUrl = ref(''); onMounted(async () => { qrUrl.value = await qrFor(shareUrl.value) })
const toast = useToast(); const copy = async () => { await navigator.clipboard.writeText(shareUrl.value); toast.ok('Lien copié') }
const wl = reactive<{ cat: any; name: string; email: string; busy: boolean }>({ cat: null, name: '', email: '', busy: false })
async function joinWait() { wl.busy = true; try { await api(`/api/events/${ev.value.id}/waitlist`, { method: 'POST', body: { categoryId: wl.cat.id, name: wl.name, email: wl.email } }); toast.ok('Tu es sur la liste d’attente. Nous te prévenons si une place se libère.'); wl.cat = null } catch (e) { toast.err(errMsg(e)) } finally { wl.busy = false } }
const report = async () => { const reason = prompt('Pourquoi signalez-vous cet événement ? (10 caractères minimum)'); if (!reason) return; try { await api(`/api/events/${ev.value.id}/report`, { method: 'POST', body: { reason } }); toast.ok('Signalement envoyé') } catch (e) { toast.err(errMsg(e)) } }
const open = computed(() => ev.value?.status === 'published' && (!ev.value.salesCloseAt || new Date(ev.value.salesCloseAt) > new Date()) && (!ev.value.salesOpenAt || new Date(ev.value.salesOpenAt) <= new Date()))
const canBuy = computed(() => open.value && ev.value?.categories.some((category: any) => category.onSale && !category.soldOut))
</script>
<template>
  <div v-if="ev" :style="vars" class="relative min-h-screen bg-bg text-fg" :class="{ 'font-serif': theme.font === 'serif' }">
    <div class="relative isolate overflow-hidden"><div class="absolute inset-0 -z-10 bg-gradient-to-br from-accent/25 via-bg to-accent2/30" /><img v-if="ev.posterUrl" :src="ev.posterUrl" alt="" class="absolute inset-0 -z-10 h-full w-full object-cover opacity-25 blur-sm"><ParticleField :intensity="0.35" :interactive="false" />
      <div class="container-x grid gap-10 py-14 lg:grid-cols-[1.2fr_1fr] lg:py-20">
        <div><div class="flex flex-wrap gap-2"><span class="chip capitalize">{{ ev.category }}</span><span v-if="ev.isDemo" class="chip text-amber-300">Événement de démonstration</span><span v-if="ev.status !== 'published'" class="chip text-amber-300">{{ ev.status === 'closed' ? 'Ventes clôturées' : 'Non publié' }}</span></div>
          <h1 class="mt-5 text-[clamp(2rem,5.5vw,4rem)] font-black">{{ ev.title }}</h1>
          <ul class="mt-6 space-y-2 text-lg"><li class="flex items-center gap-3"><CalendarDays :size="20" class="text-accent" /><span>{{ fdate(ev.startsAt) }}<span v-if="ev.endsAt"> — {{ fdate(ev.endsAt) }}</span></span></li><li v-if="ev.location" class="flex flex-wrap items-center gap-3"><MapPin :size="20" class="text-accent" /><span>{{ [ev.location.venue, ev.location.address, ev.location.city].filter(Boolean).join(', ') }}</span><a class="text-sm text-accent underline" target="_blank" rel="noopener" :href="`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(ev.location.lat !== null && ev.location.lat !== undefined && ev.location.lng !== null && ev.location.lng !== undefined ? `${ev.location.lat},${ev.location.lng}` : [ev.location.venue, ev.location.address, ev.location.city].filter(Boolean).join(', '))}`">Ouvrir Google Maps</a><a v-if="ev.location.lat !== null && ev.location.lat !== undefined && ev.location.lng !== null && ev.location.lng !== undefined" class="text-sm text-accent underline" target="_blank" rel="noopener" :href="`https://www.openstreetmap.org/?mlat=${ev.location.lat}&mlon=${ev.location.lng}#map=16/${ev.location.lat}/${ev.location.lng}`">OpenStreetMap</a></li></ul>
          <div v-if="ev.location?.lat !== null && ev.location?.lat !== undefined && ev.location?.lng !== null && ev.location?.lng !== undefined" class="mt-4 overflow-hidden rounded-xl border border-line"><iframe :src="openStreetMapEmbedUrl({ lat: ev.location.lat, lng: ev.location.lng })" :title="`Carte du lieu ${[ev.location.venue, ev.location.city].filter(Boolean).join(', ')}`" loading="lazy" referrerpolicy="no-referrer" class="h-64 w-full border-0"></iframe></div>
          <EventCountdown v-if="ev.countdownEnabled" :starts-at="ev.startsAt" :units="ev.countdownUnits" />
          <p class="mt-6 text-sm text-muted">Organisé par <strong class="text-fg">{{ ev.organizer }}</strong></p></div>
        <div class="mx-auto w-full max-w-md self-center"><img v-if="ev.posterUrl" :src="ev.posterUrl" :alt="`Affiche de ${ev.title}`" class="w-full rounded-tk border border-line shadow-deep"><TicketFace v-else tilt :title="ev.title" name="Votre nom" :seed="ev.slug" :venue="ev.location?.city || ''" /></div></div></div>
    <div class="container-x grid gap-10 py-12 lg:grid-cols-[1.2fr_1fr]">
      <div class="space-y-10">
        <section v-if="ev.description"><h2 class="text-2xl font-bold">À propos</h2><RichTextContent :content="ev.description" label="Description de l’événement" class="mt-3 max-w-prose [&_h2]:mb-2 [&_h2]:mt-5 [&_h2]:text-xl [&_h2]:font-bold [&_h3]:mb-2 [&_h3]:mt-4 [&_h3]:text-lg [&_h3]:font-semibold [&_li]:ml-5 [&_li]:list-disc [&_ol_li]:list-decimal [&_p]:mb-3 [&_strong]:font-bold [&_u]:underline" /></section>
        <section v-if="ev.faq?.length"><h2 class="text-2xl font-bold">Questions fréquentes</h2><div class="mt-4 divide-y divide-line rounded-xl border border-line px-4"><details v-for="item in ev.faq" :key="item.question" class="py-4"><summary class="cursor-pointer font-semibold">{{ item.question }}</summary><p class="mt-3 whitespace-pre-line text-sm text-muted">{{ item.answer }}</p></details></div></section>
        <section v-if="ev.gallery?.length"><h2 class="text-2xl font-bold">Galerie</h2><div class="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3"><img v-for="(g, i) in ev.gallery" :key="i" :src="g" :alt="`Photo ${Number(i) + 1} de ${ev.title}`" loading="lazy" class="aspect-square w-full rounded-xl object-cover"></div></section>
        <section><h2 class="text-2xl font-bold">Informations pratiques</h2><ul class="mt-3 list-disc space-y-1.5 pl-5 text-muted"><li>Billets au format PDF + QR code, envoyés par e-mail et téléchargeables.</li><li v-if="ev.transfersEnabled">Billets transférables à un autre participant.</li><li>{{ ev.refundPolicy?.allowed ? `Remboursement possible jusqu’à ${ev.refundPolicy.untilHoursBefore} h avant l’événement.` : 'Billets non remboursables, sauf annulation de l’événement.' }}</li><li v-if="ev.accessTerms" class="whitespace-pre-line">{{ ev.accessTerms }}</li><li v-if="ev.maxPerOrder">Maximum {{ ev.maxPerOrder }} billet{{ ev.maxPerOrder > 1 ? 's' : '' }} par commande.</li><li v-if="ev.salesOpenAt">Ouverture des ventes : {{ fdate(ev.salesOpenAt) }}.</li><li v-if="ev.salesCloseAt">Fin des ventes : {{ fdate(ev.salesCloseAt) }}.</li></ul></section>
        <section class="flex flex-wrap items-center gap-6"><div v-if="qrUrl" class="rounded-xl bg-white p-2"><img :src="qrUrl" alt="QR code vers cette page" width="120" height="120"></div><div class="space-y-3"><p class="font-bold">Partager</p><div class="flex flex-wrap gap-2"><button class="btn btn-ghost" @click="copy"><Share2 :size="16" />Copier le lien</button><a class="btn btn-ghost" target="_blank" rel="noopener" :href="`https://wa.me/?text=${encodeURIComponent(ev.title + ' ' + shareUrl)}`">WhatsApp</a></div><button class="text-xs text-muted underline" @click="report">Signaler cet événement</button></div></section>
      </div>
      <aside class="lg:sticky lg:top-24 lg:self-start"><div class="card space-y-4 p-5"><h2 class="text-xl font-bold">Billets</h2>
        <ul class="divide-y divide-line"><li v-for="c in ev.categories" :key="c.id" class="flex items-center justify-between gap-3 py-3"><div class="min-w-0"><p class="break-words font-semibold">{{ c.name }} <span v-if="ticketTypeLabel(c.kind, c.name, c.customType) !== c.name" class="chip ml-1 !py-0.5 text-accent">{{ ticketTypeLabel(c.kind, c.name, c.customType) }}</span></p><p class="text-xs" :class="c.soldOut ? 'text-red-300' : c.available <= 10 ? 'text-amber-300' : 'text-muted'">{{ c.soldOut ? 'Épuisé' : !c.onSale ? 'Vente non ouverte' : c.available <= 10 ? `Plus que ${c.available} places` : 'Disponible' }}</p></div><div class="shrink-0 text-right"><p class="font-bold">{{ c.price === 0 ? 'Gratuit' : money(c.price, ev.currency) }}</p><button v-if="c.soldOut" class="text-xs text-accent underline" @click="wl.cat = c">Liste d’attente</button></div></li></ul>
        <NuxtLink v-if="canBuy" :to="{ path: `/events/${slug}/achat`, query: { k } }" class="btn btn-primary w-full !min-h-[52px] text-base">Acheter mes billets</NuxtLink><p v-else class="rounded-xl border border-line p-3 text-center text-sm text-muted" role="status">{{ !ev.categories.length ? 'Les billets seront bientôt disponibles.' : !open ? 'La billetterie n’est pas ouverte.' : ev.categories.every((category: any) => category.soldOut) ? 'Toutes les catégories sont épuisées.' : 'Aucune catégorie n’est actuellement en vente.' }}</p>
        <p class="text-center text-xs text-muted">Paiement sécurisé via FedaPay · aucune donnée bancaire n’est conservée par TYPS</p></div>
        <form v-if="wl.cat" class="card mt-4 space-y-3 p-5" @submit.prevent="joinWait"><p class="font-bold">Liste d’attente : {{ wl.cat.name }}</p><label class="block"><span class="label">Nom</span><input v-model="wl.name" required minlength="2" class="input"></label><label class="block"><span class="label">E-mail</span><input v-model="wl.email" type="email" required class="input"></label><div class="flex gap-2"><button class="btn btn-primary flex-1" :disabled="wl.busy">Me prévenir</button><button type="button" class="btn btn-ghost" @click="wl.cat = null">Annuler</button></div></form>
      </aside>
    </div>
  </div>
</template>
